  "alarm_time" varchar(32),
  "alarm_desc" varchar(1000),
  "longitude" float8,
  "latitude" float8,
  "image_url" varchar(500),
  "handle_status" int2 NOT NULL DEFAULT 0,
  "handle_by" varchar(64),
  "handle_time" varchar(32),
  "handle_remark" varchar(500),
  "create_by" varchar(64) DEFAULT '',
  "create_time" varchar(32),
  "update_by" varchar(64) DEFAULT '',
  "update_time" varchar(32),
  "remark" varchar(500)
);
COMMENT ON COLUMN "public"."wvp_alarms"."id" IS '主键';
COMMENT ON COLUMN "public"."wvp_alarms"."protocol_type" IS '接入协议：GB28181/ISUP/ONVIF/PUSH/PULL/OTHER';
COMMENT ON COLUMN "public"."wvp_alarms"."device_id" IS '平台设备ID（国标20位编码 或 haikang_isup_序列号）';
COMMENT ON COLUMN "public"."wvp_alarms"."device_name" IS '设备名称快照';
COMMENT ON COLUMN "public"."wvp_alarms"."channel_id" IS '平台通道ID';
COMMENT ON COLUMN "public"."wvp_alarms"."channel_name" IS '通道名称快照';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_code" IS '原始报警类型码（GB AlarmType/ISUP dwAlarmType/ISAPI eventType）';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_type" IS '归一化报警类型编码';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_type_name" IS '归一化报警类型名称';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_level" IS '报警级别：1紧急 2重要 3次要 4提示';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_method" IS '国标报警方式（1电话 2设备 3短信 4GPS 5视频 6故障 7其他 8智能分析）';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_time" IS '报警发生时间';
COMMENT ON COLUMN "public"."wvp_alarms"."alarm_desc" IS '报警描述';
COMMENT ON COLUMN "public"."wvp_alarms"."longitude" IS '经度';
COMMENT ON COLUMN "public"."wvp_alarms"."latitude" IS '纬度';
COMMENT ON COLUMN "public"."wvp_alarms"."image_url" IS '报警图片地址';
COMMENT ON COLUMN "public"."wvp_alarms"."handle_status" IS '处理状态：0未处理 1已处理 2已忽略';
COMMENT ON COLUMN "public"."wvp_alarms"."handle_by" IS '处理人';
COMMENT ON COLUMN "public"."wvp_alarms"."handle_time" IS '处理时间';
COMMENT ON COLUMN "public"."wvp_alarms"."handle_remark" IS '处理备注';
COMMENT ON COLUMN "public"."wvp_alarms"."create_by" IS '创建者';
COMMENT ON COLUMN "public"."wvp_alarms"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."wvp_alarms"."update_by" IS '更新者';
COMMENT ON COLUMN "public"."wvp_alarms"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."wvp_alarms"."remark" IS '备注';
COMMENT ON TABLE "public"."wvp_alarms" IS '统一报警信息表';
