INSERT INTO "public"."sys_agreement" ("agreement_id", "agreement_type", "agreement_name", "content", "create_by", "create_time", "update_by", "update_time", "remark") VALUES (1, 'agreement', '用户协议', '<p>本协议是您与本应用运营方之间关于使用本软件所订立的协议。请您在使用前仔细阅读，使用本软件即视为同意本协议全部条款。</p><p>一、服务内容<br/>1. 本应用为视频监控综合管理平台的移动客户端，提供设备查看、通道预览、云台控制、录像回放、报警消息查看等功能。<br/>2. 部分功能需要配合服务端与流媒体服务使用，具体功能以您所在单位实际部署为准。</p><p>二、账号与使用<br/>1. 账号由所在单位管理员分配，您应妥善保管账号与密码，因个人原因泄露造成的损失由您自行承担。<br/>2. 请勿将账号出借他人使用；发现账号异常应立即修改密码并联系管理员。<br/>3. 您应在授权范围内访问设备与视频资源，不得越权访问他人数据。</p><p>三、使用规范<br/>您承诺不利用本应用从事以下行为：<br/>1. 破解、反向工程、非法抓取平台数据；<br/>2. 传播病毒、恶意代码或干扰平台正常运行；<br/>3. 未经授权录制、复制、传播监控视频内容；<br/>4. 违反法律法规、侵犯他人合法权益的其他行为。</p><p>四、知识产权<br/>本应用及其包含的源代码、界面设计、文档、商标等知识产权归运营方所有，未经书面许可不得复制、修改、传播或用于商业用途。</p><p>五、免责声明<br/>1. 视频监控服务的可用性受网络环境、设备状态、服务器负载等因素影响，我们不保证服务不中断。<br/>2. 因不可抗力（自然灾害、网络攻击、基础电信故障等）导致服务中断或数据损失，我们不承担责任。<br/>3. 本应用提供的监控画面仅供参考，不构成任何法律证据或事实认定依据。</p><p>六、协议变更与终止<br/>1. 我们有权在必要时修订本协议，修订后在应用内公示。<br/>2. 若您违反本协议任一约定，我们有权暂停或终止向您提供服务。</p><p>七、其他<br/>本协议适用中华人民共和国法律。如发生争议，双方应友好协商解决。</p>', 'admin', '2026-09-14 09:56:38', 'admin', '2026-09-14 09:56:38', NULL);
INSERT INTO "public"."sys_agreement" ("agreement_id", "agreement_type", "agreement_name", "content", "create_by", "create_time", "update_by", "update_time", "remark") VALUES (2, 'privacy', '隐私政策', '<p>本政策说明本应用如何收集、使用与保护您的个人信息。请您在使用前仔细阅读。</p><p>一、我们收集的信息<br/>1. 账号信息：您在登录时使用的用户名、密码（传输过程加密）等。<br/>2. 设备与日志信息：为保障服务稳定，我们会记录设备型号、系统版本、网络环境及操作日志。<br/>3. 业务数据：您在使用视频监控功能时产生的设备信息、通道信息、报警记录与录像记录。</p><p>二、信息的使用<br/>1. 用于完成身份认证、权限校验与账号安全管理。<br/>2. 用于提供视频点播、云台控制、录像回放、报警推送等核心功能。<br/>3. 用于排查故障、优化性能与改进产品体验。<br/>4. 法律法规要求或经您授权的其他用途。</p><p>三、信息的共享与披露<br/>我们不会向任何第三方出售您的个人信息。仅在以下情形共享：<br/>1. 获得您的明确同意；<br/>2. 为提供服务所必需（如流媒体服务节点、云存储服务）；<br/>3. 依据法律法规或监管部门强制性要求。</p><p>四、信息的存储与安全<br/>1. 您的数据存储于您所在单位部署的服务器中，我们采取加密传输、访问控制、权限分级等措施保护数据安全。<br/>2. 视频数据属于敏感信息，仅授权用户可访问，所有访问行为均有日志记录。<br/>3. 我们会按与您约定的期限保留数据，超期后按策略清理。</p><p>五、您的权利<br/>您有权访问、更正、删除您的个人信息，也有权撤回已授予的权限。可通过本应用「关于我们」中的联系方式或联系系统管理员处理。</p><p>六、未成年人信息保护<br/>本应用面向企业及行业用户，不面向未成年人提供服务。</p><p>七、政策更新<br/>本政策如有更新，我们会在应用内提示。继续使用即视为接受更新后的政策。</p>', 'admin', '2026-09-14 09:56:38', 'admin', '2026-09-14 09:56:38', NULL);
